public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 15; i++) {
            String word = "";
            if (i % 3 == 0) {
                word += "Fizz";
            }
            if (i % 5 == 0) {
                word += "Buzz";
            }
            System.out.println(word.isEmpty() ? String.valueOf(i) : word);
        }
    }
}
